#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.33.0  -  For you feed, Following, trending, ranked Clips
#
#   * Home: For you / Following switch (remembered).
#     For you puts people you are close to and fresh posts first, mixes
#     in trending posts and about 1 in 6 from new accounts; posts you
#     already scrolled past sink.  Following = only people you follow,
#     newest first.
#   * Clips: per 10 clips, 7 from people you follow or watch, 2 trending,
#     1 new.  Watching to the end / skipping is remembered.
#   * Closeness (likes, comments, shares, saves, messages, profile visits)
#     is kept on the phone only, per account, fading over two weeks.
#   * Trending is worked out by the signer at most once an hour.
#
# Run from the project root:   bash update_v1330_feed.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="03e6a4fb3aea6be67d5304087787118811224d86a9dedc2706f297d8ae302336"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f test/v1320_test.dart ] || { echo "ERROR: v1.32.0 is not installed. Run update_v1320_photo_check.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
# Some browsers save this file with Windows line endings (CRLF). Those
# extra characters corrupt the payload, so strip any control character
# sitting at the end of a line before decoding.
awk '/^__PAYLOAD__/{f=1;next} /^#/{f=0} f' "$0" | sed 's/[[:cntrl:]]*$//' | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       expected  $EXPECTED_SHA256"
  echo "       actual    $ACTUAL"
  echo "       your file is $(wc -c < "$0") bytes; it should be 7895317 bytes."
  echo "       Smaller size = the download was cut short: download it again."
  echo "       Same size but still failing, run:"
  echo "         sed -i 's/[[:cntrl:]]*$//' $(basename "$0") && bash $(basename "$0")"
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh tools/delete_user.sh tools/push_setup.sh tools/publish_rules.sh 2>/dev/null || true
# keys for the delete tool live in ~/.instantgram-admin, never in the project
touch .gitignore
for p in '*firebase-adminsdk*.json' '__pycache__/'; do
  grep -qxF "$p" .gitignore || echo "$p" >> .gitignore
done
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
if ! grep -qE "^[[:space:]]+firebase_messaging:" pubspec.yaml; then
  echo "==> Adding firebase_messaging..."
  flutter pub add firebase_messaging || { echo "ERROR: could not add firebase_messaging (internet?). Run: flutter pub add firebase_messaging"; exit 1; }
fi
if ! grep -qE "^[[:space:]]+flutter_secure_storage:" pubspec.yaml; then
  echo "==> Adding flutter_secure_storage (saved logins for account switching)..."
  flutter pub add flutter_secure_storage || { echo "ERROR: could not add flutter_secure_storage (internet?). Run: flutter pub add flutter_secure_storage"; exit 1; }
fi

if ! grep -qE "^[[:space:]]+tflite_flutter:" pubspec.yaml; then
  echo "==> Adding tflite_flutter (the photo check engine)..."
  flutter pub add tflite_flutter || { echo "ERROR: could not add tflite_flutter (internet?). Run: flutter pub add tflite_flutter"; exit 1; }
fi
echo ""
echo "==> Android: minimum version 8.0 and shrinker rules (photo check)..."
python3 - <<'PYSDK'
import re
done = False
for g in ["android/app/build.gradle.kts", "android/app/build.gradle"]:
    try:
        s = open(g).read()
    except FileNotFoundError:
        continue
    n = s
    if g.endswith(".kts"):
        n = re.sub(r"maxOf\(\s*flutter\.minSdkVersion\s*,\s*\d+\s*\)", "maxOf(flutter.minSdkVersion, 26)", n)
        n = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion\b", "minSdk = maxOf(flutter.minSdkVersion, 26)", n)
        n = re.sub(r"minSdk\s*=\s*(2[0-5]|1\d)\b", "minSdk = 26", n)
    else:
        n = re.sub(r"Math\.max\(\s*flutter\.minSdkVersion\s*,\s*\d+\s*\)", "Math.max(flutter.minSdkVersion, 26)", n)
        n = re.sub(r"minSdk(Version)?(\s*=\s*|\s+)flutter\.minSdkVersion\b", lambda mo: "minSdk%s%sMath.max(flutter.minSdkVersion, 26)" % (mo.group(1) or "", mo.group(2)), n)
        n = re.sub(r"minSdk(Version)?(\s*=\s*|\s+)(2[0-5]|1\d)\b", lambda mo: "minSdk%s%s26" % (mo.group(1) or "", mo.group(2)), n)
    done = True
    if n != s:
        open(g, "w").write(n)
        print("    %s: minimum Android version set to 8.0" % g)
    else:
        print("    %s: minimum Android version already fine" % g)
if not done:
    print("    WARNING: android/app/build.gradle(.kts) not found. Set minSdk to 26 by hand.")
p = "android/app/proguard-rules.pro"
try:
    cur = open(p).read()
except FileNotFoundError:
    cur = ""
if "org.tensorflow.lite" not in cur:
    with open(p, "a") as f:
        f.write(("\n" if cur and not cur.endswith("\n") else "") +
                "# tflite_flutter (photo check): the optional GPU delegate is not part of the app\n"
                "-keep class org.tensorflow.lite.** { *; }\n"
                "-dontwarn org.tensorflow.lite.gpu.**\n")
    print("    %s: TensorFlow Lite rules added" % p)
PYSDK
echo ""
echo "==> Adding the moment fonts to pubspec.yaml..."
python3 - pubspec.yaml <<'PYFONTS'
import re, sys
p = sys.argv[1] if len(sys.argv) > 1 else "pubspec.yaml"
s = open(p).read()
fams = [("Bebas", "BebasNeue-Regular.ttf"), ("Marker", "PermanentMarker-Regular.ttf"),
        ("Lobster", "Lobster-Regular.ttf"), ("Caveat", "Caveat-Variable.ttf"),
        ("Playfair", "PlayfairDisplay-Variable.ttf"), ("SpaceMono", "SpaceMono-Bold.ttf")]
add = ""
for fam, file in fams:
    if not re.search(r"family:\s*" + fam + r"\s*$", s, re.M):
        add += "    - family: %s\n      fonts:\n        - asset: assets/fonts/%s\n" % (fam, file)
if add:
    m = re.search(r"^  fonts:[ \t]*\r?\n", s, re.M)
    if m:
        s = s[:m.end()] + add + s[m.end():]
    else:
        m2 = re.search(r"^  uses-material-design:[ \t]*true[ \t]*\r?\n", s, re.M) or re.search(r"^flutter:[ \t]*\r?\n", s, re.M)
        if not m2:
            sys.exit("ERROR: no flutter: section in pubspec.yaml")
        s = s[:m2.end()] + "  fonts:\n" + add + s[m2.end():]
    open(p, "w").write(s)
    print("    pubspec.yaml: added the moment text fonts")
PYFONTS

echo ""
echo "==> App icons (pubspec.yaml + AndroidManifest.xml)..."
python3 - pubspec.yaml <<'PYICONS'
import re, sys
p = sys.argv[1]
s = open(p).read()
if "assets/app_icons/" not in s:
    m = re.search(r"^([ \t]*)- assets/logo/[ \t]*$", s, re.M)
    if m:
        s = s[:m.end()] + "\n" + m.group(1) + "- assets/app_icons/" + s[m.end():]
    elif re.search(r"^  assets:[ \t]*$", s, re.M):
        s = re.sub(r"^  assets:[ \t]*$", "  assets:\n    - assets/app_icons/", s, count=1, flags=re.M)
    else:
        sys.exit("ERROR: no assets: section in pubspec.yaml")
    open(p, "w").write(s)
    print("    pubspec.yaml: added assets/app_icons/")
else:
    print("    pubspec.yaml: assets/app_icons/ already there")
PYICONS
python3 tools/patch_app_icons.py

echo "Done. v1.33.0 is in place."
echo ""
echo "Also needed (once):"
echo "  1. Redeploy the signer in Vercel (signer/ changed: new /api/trending)."
echo "  2. Push to GitHub (step 3 of the usual flow)."
exit 0

